// Normalize every entry to just the fields the game engine actually reads.
window.GRID_PLAYERS = window.GRID_PLAYERS.map(function (p) {
  return {
    name: p.name,
    teams: p.teams || [],
    position: p.position,
    draft: p.draft || { round: 0, year: null },
    college: p.college || "",
    hof: !!p.hof,
    mvp: !!p.mvp,
    sbChamp: !!p.sbChamp,
    sbMVP: !!p.sbMVP,
    proBowls: p.proBowls || 0,
    allPro: p.allPro || 0,
    roty: !!p.roty
  };
});

// Criteria library: each entry is testable against a GRID_PLAYERS row.
// type "team" criteria are used to guarantee at least the classic
// team-by-team grid feel; type "stat" criteria cover draft/awards/position.
window.GRID_CRITERIA = (function () {
  var teamCriteria = Object.keys(window.GRID_TEAM_NAMES).map(function (code) {
    return {
      id: "team_" + code,
      type: "team",
      team: code,
      label: window.GRID_TEAM_NAMES[code],
      test: function (p) { return p.teams.indexOf(code) !== -1; }
    };
  });

  var statCriteria = [
    { id: "pos_qb", type: "stat", label: "Quarterback", test: function (p) { return p.position === "QB"; } },
    { id: "pos_rb", type: "stat", label: "Running Back", test: function (p) { return p.position === "RB"; } },
    { id: "pos_wr", type: "stat", label: "Wide Receiver", test: function (p) { return p.position === "WR"; } },
    { id: "pos_te", type: "stat", label: "Tight End", test: function (p) { return p.position === "TE"; } },
    { id: "pos_dl", type: "stat", label: "Defensive Line (DE/DT/EDGE)", test: function (p) { return p.position === "DE" || p.position === "DT" || p.position === "EDGE"; } },
    { id: "pos_lb", type: "stat", label: "Linebacker", test: function (p) { return p.position === "LB"; } },
    { id: "pos_db", type: "stat", label: "Defensive Back (CB/S)", test: function (p) { return p.position === "CB" || p.position === "S"; } },
    { id: "pos_ol", type: "stat", label: "Offensive Line (OT/OG/C)", test: function (p) { return p.position === "OT" || p.position === "OG" || p.position === "C"; } },
    { id: "draft_r1", type: "stat", label: "1st Round Pick", test: function (p) { return p.draft.round === 1; } },
    { id: "draft_undrafted", type: "stat", label: "Undrafted", test: function (p) { return p.draft.round === 0; } },
    { id: "draft_day2plus", type: "stat", label: "Drafted Round 3 or Later", test: function (p) { return p.draft.round >= 3; } },
    { id: "hof", type: "stat", label: "Pro Football Hall of Famer", test: function (p) { return p.hof; } },
    { id: "mvp", type: "stat", label: "NFL MVP", test: function (p) { return p.mvp; } },
    { id: "sb_champ", type: "stat", label: "Super Bowl Champion", test: function (p) { return p.sbChamp; } },
    { id: "sb_mvp", type: "stat", label: "Super Bowl MVP", test: function (p) { return p.sbMVP; } },
    { id: "roty", type: "stat", label: "Rookie of the Year", test: function (p) { return p.roty; } },
    { id: "probowl_5plus", type: "stat", label: "5+ Pro Bowls", test: function (p) { return p.proBowls >= 5; } },
    { id: "probowl_10plus", type: "stat", label: "10+ Pro Bowls", test: function (p) { return p.proBowls >= 10; } },
    { id: "allpro_3plus", type: "stat", label: "3+ First-Team All-Pro", test: function (p) { return p.allPro >= 3; } },
    { id: "multi_team", type: "stat", label: "Played for 3+ Teams", test: function (p) { return p.teams.length >= 3; } },
    { id: "one_team", type: "stat", label: "Played for Only 1 Team", test: function (p) { return p.teams.length === 1; } }
  ];

  return { team: teamCriteria, stat: statCriteria, all: teamCriteria.concat(statCriteria) };
})();
